$positionInfo=$positions->map(fn($p)=>['id'=>$p->id,'lot'=>$p->stock_lot_id,'roll'=>$p->fabric_roll_id,'tracked'=>(bool)$p->fabric_roll_id,'available'=>$p->available_quantity,'onHand'=>bcadd($p->ledger_on_hand,'0',6),'label'=>$p->lot->lot_number.' / '.($p->roll?->roll_number??'Unrolled').' / '.$p->location->warehouse->name.' / '.$p->location->name])->values()->all();
$config=['kind'=>$kind,'lines'=>array_values($rows),'defaults'=>$defaults,'orderInfo'=>$orderInfo,'receiptInfo'=>$receiptInfo,'positionInfo'=>$positionInfo];
